<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();$id=(int)$u['id'];$where=["u.id<>?","u.status='active'"];$args=[$id];$search=trim($_GET['q']??'');$course=trim($_GET['course']??'');$semester=trim($_GET['semester']??'');$mode=trim($_GET['mode']??'');$subject=(int)($_GET['subject']??0);$skill=(int)($_GET['skill']??0);if($search){$where[]='(u.name LIKE ? OR p.course LIKE ? OR p.college LIKE ?)';array_push($args,"%$search%","%$search%","%$search%");}if($course){$where[]='p.course LIKE ?';$args[]="%$course%";}if($semester){$where[]='p.semester=?';$args[]=(int)$semester;}if($mode){$where[]='p.study_mode IN (?,\'Both\')';$args[]=$mode;}if($subject){$where[]='EXISTS(SELECT 1 FROM user_subjects us WHERE us.user_id=u.id AND us.subject_id=?)';$args[]=$subject;}if($skill){$where[]='EXISTS(SELECT 1 FROM user_skills us WHERE us.user_id=u.id AND us.skill_id=?)';$args[]=$skill;}$sql='SELECT u.id,u.name,p.college,p.course,p.semester,p.study_mode,p.availability_days FROM users u JOIN student_profiles p ON p.user_id=u.id WHERE '.implode(' AND ',$where).' ORDER BY u.name LIMIT 60';$q=db()->prepare($sql);$q->execute($args);$people=[];foreach($q as $r){$m=match_info($id,(int)$r['id']);$r['score']=$m['score'];$r['why']=$m['why'];$q2=db()->prepare('SELECT s.name FROM user_subjects x JOIN subjects s ON s.id=x.subject_id WHERE x.user_id=? AND x.intent=\'help\' LIMIT 3');$q2->execute([$r['id']]);$r['tags']=array_column($q2->fetchAll(),'name');$people[]=$r;}usort($people,fn($a,$b)=>$b['score']<=>$a['score']);$subjects=db()->query('SELECT id,name FROM subjects WHERE active=1 ORDER BY name')->fetchAll();$skills=db()->query('SELECT id,name FROM skills WHERE active=1 ORDER BY name')->fetchAll();page_start('Find partners'); ?><div class="card mb-4"><div class="card-body"><form class="row g-2"><div class="col-md-3"><input class="form-control" name="q" placeholder="Name, college, course" value="<?= e($search) ?>"></div><div class="col-md-2"><input class="form-control" name="course" placeholder="Course" value="<?= e($course) ?>"></div><div class="col-md-1"><input class="form-control" type="number" name="semester" placeholder="Sem" value="<?= e($semester) ?>"></div><div class="col-md-2"><select class="form-select" name="subject"><option value="">Any subject</option><?php foreach($subjects as $s): ?><option value="<?= $s['id'] ?>" <?= $subject===$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach ?></select></div><div class="col-md-2"><select class="form-select" name="skill"><option value="">Any skill</option><?php foreach($skills as $s): ?><option value="<?= $s['id'] ?>" <?= $skill===$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach ?></select></div><div class="col-md-1"><select class="form-select" name="mode"><option value="">Mode</option><?php foreach(['Online','Offline'] as $m): ?><option <?= $mode===$m?'selected':'' ?>><?= $m ?></option><?php endforeach ?></select></div><div class="col-md-1"><button class="btn btn-primary w-100">Find</button></div></form></div></div><div class="row g-3"><?php foreach($people as $r): ?><div class="col-md-6 col-xl-4"><div class="card h-100"><div class="card-body"><div class="d-flex gap-3 align-items-center"><div class="avatar"><?= e(mb_substr($r['name'],0,1)) ?></div><div><h2 class="h6 fw-bold mb-1"><?= e($r['name']) ?></h2><div class="small text-secondary"><?= e($r['course']) ?> · Sem <?= e($r['semester']) ?></div></div><div class="ms-auto match"><?= $r['score'] ?>%</div></div><div class="small text-secondary mt-3"><i class="bi bi-building"></i> <?= e($r['college']) ?></div><div class="my-2"><?php foreach($r['tags'] as $t)echo tag($t); ?></div><div class="small text-secondary mb-3"><?= e($r['study_mode']?:'Study mode not set') ?> · <?= e($r['availability_days']?:'Availability not set') ?></div><div class="small mb-3"><strong>Why you match:</strong> <?= e(implode(', ',$r['why'])?:'A chance to meet a new learning peer') ?></div><a class="btn btn-sm btn-outline-primary" href="partner-details.php?id=<?= (int)$r['id'] ?>">View profile</a> <form class="d-inline" method="post" action="../actions/partner-request.php"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="receiver_id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="intent" value="send"><button class="btn btn-sm btn-primary">Send request</button></form></div></div></div><?php endforeach ?><?php if(!$people): ?><div class="col-12"><div class="card empty">No students match those filters yet. Try broadening your search.</div></div><?php endif ?></div><?php page_end(); ?>
